record Counter { n: Int64 }
impl Counter {
    fn bump(mut self) -> Int64 {
        self.n = self.n + 1
        self.n
    }
}
pub type AppError = Failed(String)
pub fn main() -> Result<(), AppError> {
    let c = Counter { n: 0 }
    let n = c.bump()
    return Ok(())
}

